    <style>
        :root{--ink:#1f2228;--muted:#6e737d;--line:#e2e4e7;--paper:#f7f7f6;--red:#bd1712;--dark:#202225;--kosud:#167449;--spektrum:#247dae}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}.wrap{width:min(1160px,calc(100% - 48px));margin:auto}.nav{height:76px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.9);backdrop-filter:blur(12px)}.nav-in{display:flex;height:100%;align-items:center;justify-content:space-between}.brand{color:var(--red);font-size:18px;font-weight:800;letter-spacing:-.04em;text-decoration:none}.nav-links{display:flex;align-items:center;gap:26px}.nav-links a{color:#5c626a;font-size:13px;font-weight:700;text-decoration:none}.nav-links a:hover,.nav-links a.active{color:var(--red)}.hero{padding:80px 0 68px;background:#fff;border-bottom:1px solid var(--line)}.kicker{margin:0 0 18px;color:var(--red);font:500 11px 'DM Mono',monospace;letter-spacing:.13em;text-transform:uppercase}.hero-grid{display:grid;grid-template-columns:minmax(0,1fr) 325px;gap:80px;align-items:end}.hero h1{max-width:720px;margin:0;font-size:clamp(42px,5.3vw,66px);line-height:1.04;letter-spacing:-.065em}.hero h1 em{color:var(--red);font-style:normal}.hero p{max-width:650px;margin:22px 0 0;color:var(--muted);font-size:16px;line-height:1.75}.hero-note{padding:21px 22px;border-left:3px solid var(--red);background:#f9f4f3;color:#5b5250;font-size:13px;line-height:1.6}.hero-note b{display:block;margin-bottom:4px;color:#7e1712;font-size:12px}.portfolio{padding:68px 0 82px}.project{margin-bottom:62px}.project:last-child{margin-bottom:0}.project-top{display:flex;align-items:end;justify-content:space-between;gap:25px;margin-bottom:22px}.project-title{display:flex;align-items:center;gap:14px}.project-index{font:500 11px 'DM Mono',monospace;letter-spacing:.1em}.project h2{margin:0;font-size:31px;letter-spacing:-.055em}.project-top p{max-width:410px;margin:0;color:var(--muted);font-size:13px;line-height:1.6;text-align:right}.project-shell{overflow:hidden;border:1px solid var(--line);background:#fff}.project-shell.kosud{border-top:4px solid var(--kosud)}.project-shell.spektrum{border-top:4px solid var(--spektrum)}.project-intro{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:19px 22px;border-bottom:1px solid var(--line)}.project-intro strong{font-size:14px}.project-intro span{font:10px 'DM Mono',monospace;letter-spacing:.07em;color:#71808a}.screens{display:grid;grid-template-columns:repeat(2,1fr)}.screen{min-width:0;padding:18px;border-right:1px solid var(--line)}.screen:last-child{border-right:0}.screen figure{margin:0;overflow:hidden;border:1px solid #dce3e6;background:#edf2f4}.screen img{display:block;width:100%;height:280px;object-fit:cover;object-position:top;transition:transform .35s ease}.screen:hover img{transform:scale(1.025)}.screen figcaption{padding:12px 0 0;color:#596771;font-size:12px;font-weight:700}.screen figcaption span{display:block;margin-top:3px;color:#89949b;font-size:11px;font-weight:400}.footer{padding:27px 0;background:var(--dark);color:#c2c7cb}.footer-in{display:flex;justify-content:space-between;gap:16px;font:10px 'DM Mono',monospace}@media(max-width:760px){.nav-links{gap:16px}.hero{padding:58px 0}.hero-grid{grid-template-columns:1fr;gap:33px}.project-top{align-items:start;flex-direction:column}.project-top p{text-align:left}.screens{grid-template-columns:1fr}.screen{border-right:0;border-bottom:1px solid var(--line)}.screen:last-child{border-bottom:0}.screen img{height:250px}}@media(max-width:520px){.wrap{width:min(100% - 36px,1160px)}.nav{height:67px}.nav-links a:not(.active){display:none}.hero h1{font-size:40px}.hero p{font-size:14px}.portfolio{padding:45px 0}.project{margin-bottom:45px}.project h2{font-size:27px}.project-intro{align-items:start;flex-direction:column}.footer-in{flex-direction:column}}
